from pathlib import Path
import pandas as pd,numpy as np,json
P=Path(__file__).resolve().parents[1];V=P/'私有数据';O=P/'结果';L=pd.read_pickle(V/'MIMIC_common_labs.pkl');old=L.value_std.notna();censored=L.value.fillna('').str.contains(r'[<>≤≥]',regex=True);L['number']=L.valuenum.where(~censored);L['value_std']=L.number*L.factor
bounds={'hb':(20,250),'cr':(5,5000),'alb':(5,70),'wbc':(.1,200),'platelet':(1,2000),'na':(80,200),'k':(1,12),'glucose':(.5,100)};bad=np.array([not lo<=v<=hi if pd.notna(v) else False for v,(lo,hi) in zip(L.value_std,L.variable.map(bounds))]);L.loc[bad,'value_std']=np.nan
L['previous_valid']=old;L['recovered_numeric']=~old&L.value_std.notna();L['placeholder_numeric']=L.value.fillna('').eq('___')&L.valuenum.notna();audit=L.groupby('variable').agg(rows=('value_std','size'),previous_valid=('previous_valid','sum'),corrected_valid=('value_std','count'),recovered_numeric=('recovered_numeric','sum'),placeholder_numeric=('placeholder_numeric','sum'));audit.to_csv(O/'结构化数值修正审计.csv');L.drop(columns=['previous_valid','recovered_numeric','placeholder_numeric']).to_pickle(V/'MIMIC_common_labs.pkl')
qc=json.loads((O/'extraction_qc.json').read_text(encoding='utf8'));qc.update({'numeric_policy':'valuenum with units/range checks, exclude explicit censoring; placeholder text does not invalidate numeric field','numeric_correction_completed':True,'explicit_censored':int(censored.sum()),'range_invalid':int(bad.sum()),'recovered_values':int(L.recovered_numeric.sum())});(O/'extraction_qc.json').write_text(json.dumps(qc,indent=2),encoding='utf8');print('NUMERIC_CORRECTED')
